import json, pandas as pd, numpy as np
for fn in ['facts.json','skipped.json']:
    obj=json.load(open(fn)); print(fn, len(obj))
for f in json.load(open('facts.json')):
    ns={k:pd.read_csv(v) for k,v in f['tables'].items()}
    print('\n'+f['id'])
    print(eval(f['code'],{'pd':pd,'np':np,**ns}))
EOF

